#include <vector>
#include <sstream>
#include <algorithm>

using namespace std;

map<string, bool> bmap;
int card[10];
int selected[4], temp[4];
bool used[10];
int n, k, num;

void solve(int m) {
    if (m == k) {
        for (int i = 0; i < k; i++) temp[i] = selected[i];
