    } else {
        for (int i = 0; i < n; i++) {
            if (!used[i]) {
                used[i] = true;
                selected[m] = card[i];
                solve(m + 1);
                used[i] = false;
            }
        }
    }
}

int main() {
    while (scanf("%d %d", &n, &k), n) {
        for (int i = 0; i < n; i++) scanf("%d", &card[i]);
        fill(used, used + 10, 0);
        bmap.clear();
        num = 0;
        solve(0);
        printf("%d\n", num);
